$chapters = @"

,  {"id":"SAT-10-10-01","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'aberration' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"deviation from normal"},{"id":"b","text":"normal occurrence"},{"id":"c","text":"celebration"},{"id":"d","text":"abbreviation"}],"correctOptionId":"a","explanation":"Aberration means a departure from what is normal or expected.","difficulty":"Easy"},
  {"id":"SAT-10-10-02","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'meticulous' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"extremely careful"},{"id":"b","text":"careless"},{"id":"c","text":"hasty"},{"id":"d","text":"lazy"}],"correctOptionId":"a","explanation":"Meticulous means showing great attention to detail.","difficulty":"Easy"},
  {"id":"SAT-10-10-03","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'resilient' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"able to recover quickly"},{"id":"b","text":"fragile"},{"id":"c","text":"permanent"},{"id":"d","text":"rigid"}],"correctOptionId":"a","explanation":"Resilient means able to withstand or recover quickly from difficult conditions.","difficulty":"Easy"},
  {"id":"SAT-10-10-04","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'benevolent' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"kind and generous"},{"id":"b","text":"cruel"},{"id":"c","text":"indifferent"},{"id":"d","text":"selfish"}],"correctOptionId":"a","explanation":"Benevolent means well-meaning and kindly.","difficulty":"Easy"},
  {"id":"SAT-10-10-05","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'ephemeral' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"short-lived"},{"id":"b","text":"permanent"},{"id":"c","text":"eternal"},{"id":"d","text":"constant"}],"correctOptionId":"a","explanation":"Ephemeral means lasting for a very short time.","difficulty":"Easy"},
  {"id":"SAT-10-10-06","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'articulate' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"express clearly"},{"id":"b","text":"mumble"},{"id":"c","text":"whisper"},{"id":"d","text":"scream"}],"correctOptionId":"a","explanation":"Articulate means to express thoughts clearly and fluently.","difficulty":"Easy"},
  {"id":"SAT-10-10-07","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'lethargic' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"sluggish and tired"},{"id":"b","text":"energetic"},{"id":"c","text":"alert"},{"id":"d","text":"active"}],"correctOptionId":"a","explanation":"Lethargic means affected by a lack of energy; sluggish.","difficulty":"Easy"},
  {"id":"SAT-10-10-08","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'pragmatic' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"practical"},{"id":"b","text":"idealistic"},{"id":"c","text":"theoretical"},{"id":"d","text":"romantic"}],"correctOptionId":"a","explanation":"Pragmatic means dealing with things sensibly and realistically.","difficulty":"Easy"},
  {"id":"SAT-10-10-09","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'tenacious' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"persistent"},{"id":"b","text":"weak"},{"id":"c","text":"yielding"},{"id":"d","text":"lazy"}],"correctOptionId":"a","explanation":"Tenacious means holding firmly to something; persistent.","difficulty":"Easy"},
  {"id":"SAT-10-10-10","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'eloquent' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"fluent and persuasive"},{"id":"b","text":"inarticulate"},{"id":"c","text":"quiet"},{"id":"d","text":"confused"}],"correctOptionId":"a","explanation":"Eloquent means fluent or persuasive in speaking or writing.","difficulty":"Easy"},
  {"id":"SAT-10-10-11","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'ambiguous' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"open to multiple interpretations"},{"id":"b","text":"clear"},{"id":"c","text":"obvious"},{"id":"d","text":"certain"}],"correctOptionId":"a","explanation":"Ambiguous means open to more than one interpretation.","difficulty":"Medium"},
  {"id":"SAT-10-10-12","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'conundrum' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"puzzle"},{"id":"b","text":"answer"},{"id":"c","text":"solution"},{"id":"d","text":"certainty"}],"correctOptionId":"a","explanation":"Conundrum means a confusing and difficult problem or question.","difficulty":"Medium"},
  {"id":"SAT-10-10-13","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'paradox' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"self-contradiction"},{"id":"b","text":"agreement"},{"id":"c","text":"confirmation"},{"id":"d","text":"certainty"}],"correctOptionId":"a","explanation":"A paradox is a seemingly contradictory statement that may be true.","difficulty":"Medium"},
  {"id":"SAT-10-10-14","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'candid' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"honest and direct"},{"id":"b","text":"deceptive"},{"id":"c","text":"secretive"},{"id":"d","text":"evasive"}],"correctOptionId":"a","explanation":"Candid means truthful and straightforward.","difficulty":"Medium"},
  {"id":"SAT-10-10-15","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'diligent' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"hardworking"},{"id":"b","text":"lazy"},{"id":"c","text":"careless"},{"id":"d","text":"sloppy"}],"correctOptionId":"a","explanation":"Diligent means having or showing care in one's work.","difficulty":"Medium"},
  {"id":"SAT-10-10-16","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'innate' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"inborn"},{"id":"b","text":"learned"},{"id":"c","text":"acquired"},{"id":"d","text":"taught"}],"correctOptionId":"a","explanation":"Innate means inborn; natural rather than learned.","difficulty":"Medium"},
  {"id":"SAT-10-10-17","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'plausible' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":" believable"},{"id":"b","text":"impossible"},{"id":"c","text":"absurd"},{"id":"d","text":"unreasonable"}],"correctOptionId":"a","explanation":"Plausible means seeming reasonable or probable.","difficulty":"Medium"},
  {"id":"SAT-10-10-18","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'verbose' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"wordy"},{"id":"b","text":"brief"},{"id":"c","text":"concise"},{"id":"d","text":"terse"}],"correctOptionId":"a","explanation":"Verbose means using more words than needed; wordy.","difficulty":"Medium"},
  {"id":"SAT-10-10-19","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'perfunctory' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"done without care"},{"id":"b","text":"thorough"},{"id":"c","text":"meticulous"},{"id":"d","text":"careful"}],"correctOptionId":"a","explanation":"Perfunctory means carried out with minimal effort or thought.","difficulty":"Medium"},
  {"id":"SAT-10-10-20","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'acquiesce' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"accept reluctantly"},{"id":"b","text":"resist strongly"},{"id":"c","text":"refuse completely"},{"id":"d","text":"fight against"}],"correctOptionId":"a","explanation":"Acquiesce means to accept something reluctantly without protest.","difficulty":"Medium"},
  {"id":"SAT-10-10-21","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'sycophant' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"flatterer"},{"id":"b","text":"critic"},{"id":"c","text":"enemy"},{"id":"d","text":"opponent"}],"correctOptionId":"a","explanation":"A sycophant is a person who flatters someone important.","difficulty":"Hard"},
  {"id":"SAT-10-10-22","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'obsequious' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"excessively obedient"},{"id":"b","text":"defiant"},{"id":"c","text":"independent"},{"id":"d","text":"rebellious"}],"correctOptionId":"a","explanation":"Obsequious means obedient or attentive to an excessive degree.","difficulty":"Hard"},
  {"id":"SAT-10-10-23","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'laconic' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"using few words"},{"id":"b","text":"verbose"},{"id":"c","text":"talkative"},{"id":"d","text":"wordy"}],"correctOptionId":"a","explanation":"Laconic means using very few words; concise to the point of seeming rude.","difficulty":"Hard"},
  {"id":"SAT-10-10-24","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'capricious' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"unpredictable"},{"id":"b","text":"steady"},{"id":"c","text":"consistent"},{"id":"d","text":"reliable"}],"correctOptionId":"a","explanation":"Capricious means given to sudden and unaccountable changes of mood or behavior.","difficulty":"Hard"},
  {"id":"SAT-10-10-25","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'dogmatic' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"opinionated"},{"id":"b","text":"open-minded"},{"id":"c","text":"flexible"},{"id":"d","text":"tolerant"}],"correctOptionId":"a","explanation":"Dogmatic means inclined to lay down principles as truths.","difficulty":"Hard"},
  {"id":"SAT-10-10-26","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'equivocal' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"ambiguous"},{"id":"b","text":"clear"},{"id":"c","text":"definite"},{"id":"d","text":"certain"}],"correctOptionId":"a","explanation":"Equivocal means open to more than one interpretation; ambiguous.","difficulty":"Hard"},
  {"id":"SAT-10-10-27","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'auspicious' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"favorable"},{"id":"b","text":"unlucky"},{"id":"c","text":"ominous"},{"id":"d","text":"threatening"}],"correctOptionId":"a","explanation":"Auspicious means conducive to success; favorable.","difficulty":"Hard"},
  {"id":"SAT-10-10-28","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'enervate' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"drain of energy"},{"id":"b","text":"energize"},{"id":"c","text":"invigorate"},{"id":"d","text":"stimulate"}],"correctOptionId":"a","explanation":"Enervate means to cause someone to feel drained of energy.","difficulty":"Hard"},
  {"id":"SAT-10-10-29","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'recalcitrant' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"uncooperative"},{"id":"b","text":"obedient"},{"id":"c","text":"compliant"},{"id":"d","text":"agreeable"}],"correctOptionId":"a","explanation":"Recalcitrant means having an obstinately uncooperative attitude.","difficulty":"Hard"},
  {"id":"SAT-10-10-30","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 10: Vocabulary in Context","yearEC":"2024 E.C.","questionText":"The word 'gregarious' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"sociable"},{"id":"b","text":"introverted"},{"id":"c","text":"antisocial"},{"id":"d","text":"lonely"}],"correctOptionId":"a","explanation":"Gregarious means fond of company; sociable.","difficulty":"Hard"},
  {"id":"SAT-10-11-01","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"When reading a bar graph, the y-axis typically shows:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"values or amounts"},{"id":"b","text":"categories"},{"id":"c","text":"time"},{"id":"d","text":"labels"}],"correctOptionId":"a","explanation":"The y-axis typically represents the numerical values being measured.","difficulty":"Easy"},
  {"id":"SAT-10-11-02","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"A line graph is best used to show:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"trends over time"},{"id":"b","text":"parts of a whole"},{"id":"c","text":"comparisons"},{"id":"d","text":"distributions"}],"correctOptionId":"a","explanation":"Line graphs are ideal for showing how data changes over time.","difficulty":"Easy"},
  {"id":"SAT-10-11-03","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"A pie chart represents:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"parts of a whole"},{"id":"b","text":"changes over time"},{"id":"c","text":"correlations"},{"id":"d","text":"frequencies"}],"correctOptionId":"a","explanation":"Pie charts show proportions of a whole as slices.","difficulty":"Easy"},
  {"id":"SAT-10-11-04","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"To find the median from a frequency table, you:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"find the middle value"},{"id":"b","text":"add all values"},{"id":"c","text":"find the most common"},{"id":"d","text":"find the range"}],"correctOptionId":"a","explanation":"The median is the middle value when data is ordered.","difficulty":"Easy"},
  {"id":"SAT-10-11-05","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"A scatter plot shows:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"relationship between two variables"},{"id":"b","text":"single data point"},{"id":"c","text":"parts of a whole"},{"id":"d","text":"rankings"}],"correctOptionId":"a","explanation":"Scatter plots show the relationship between two numerical variables.","difficulty":"Easy"},
  {"id":"SAT-10-11-06","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"The title of a graph should:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"describe the data shown"},{"id":"b","text":"be entertaining"},{"id":"c","text":"be very long"},{"id":"d","text":"be unclear"}],"correctOptionId":"a","explanation":"A clear title helps readers understand what data is being presented.","difficulty":"Easy"},
  {"id":"SAT-10-11-07","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"A histogram shows:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"frequency distribution"},{"id":"b","text":"trends"},{"id":"c","text":"proportions"},{"id":"d","text":"correlations"}],"correctOptionId":"a","explanation":"Histograms show the frequency distribution of continuous data.","difficulty":"Easy"},
  {"id":"SAT-10-11-08","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"To compare two groups, which is most appropriate?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"side-by-side bar graph"},{"id":"b","text":"single pie chart"},{"id":"c","text":"line graph"},{"id":"d","text":"single bar"}],"correctOptionId":"a","explanation":"Side-by-side bar graphs allow direct comparison between groups.","difficulty":"Easy"},
  {"id":"SAT-10-11-09","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"The slope of a line on a graph represents:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"rate of change"},{"id":"b","text":"total amount"},{"id":"c","text":"starting point"},{"id":"d","text":"end point"}],"correctOptionId":"a","explanation":"Slope shows the rate of change between variables.","difficulty":"Easy"},
  {"id":"SAT-10-11-10","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"A table is useful for:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"showing exact values"},{"id":"b","text":"showing trends only"},{"id":"c","text":"showing proportions"},{"id":"d","text":"showing relationships"}],"correctOptionId":"a","explanation":"Tables present exact numerical values in an organized format.","difficulty":"Easy"},
  {"id":"SAT-10-11-11","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"What does the x-intercept represent?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"where y = 0"},{"id":"b","text":"where x = 0"},{"id":"c","text":"the slope"},{"id":"d","text":"the maximum"}],"correctOptionId":"a","explanation":"The x-intercept is where the line crosses the x-axis, where y = 0.","difficulty":"Medium"},
  {"id":"SAT-10-11-12","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"A positive correlation means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"as x increases, y increases"},{"id":"b","text":"as x increases, y decreases"},{"id":"c","text":"no relationship"},{"id":"d","text":"x decreases"}],"correctOptionId":"a","explanation":"Positive correlation: both variables increase together.","difficulty":"Medium"},
  {"id":"SAT-10-11-13","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"An outlier in a data set:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"is far from other values"},{"id":"b","text":"is the average"},{"id":"c","text":"is the most common"},{"id":"d","text":"is the median"}],"correctOptionId":"a","explanation":"An outlier is a data point significantly different from others.","difficulty":"Medium"},
  {"id":"SAT-10-11-14","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"The range of a data set is:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"maximum - minimum"},{"id":"b","text":"sum of values"},{"id":"c","text":"average"},{"id":"d","text":"most common"}],"correctOptionId":"a","explanation":"Range = maximum value - minimum value.","difficulty":"Medium"},
  {"id":"SAT-10-11-15","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"A double bar graph is used to:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"compare two sets of data"},{"id":"b","text":"show one data set"},{"id":"c","text":"show trends only"},{"id":"d","text":"show proportions"}],"correctOptionId":"a","explanation":"Double bar graphs compare two related data sets.","difficulty":"Medium"},
  {"id":"SAT-10-11-16","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"To determine the percent increase from graph data:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"(new - old)/old x 100"},{"id":"b","text":"old/new x 100"},{"id":"c","text":"new/old x 100"},{"id":"d","text":"old - new"}],"correctOptionId":"a","explanation":"Percent increase = (new value - old value)/old value x 100.","difficulty":"Medium"},
  {"id":"SAT-10-11-17","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"A box plot shows:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"five-number summary"},{"id":"b","text":"individual data points"},{"id":"c","text":"correlation"},{"id":"d","text":"cause and effect"}],"correctOptionId":"a","explanation":"Box plots display the five-number summary: min, Q1, median, Q3, max.","difficulty":"Medium"},
  {"id":"SAT-10-11-18","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"The mean is affected by:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"outliers"},{"id":"b","text":"sample size"},{"id":"c","text":"median"},{"id":"d","text":"mode"}],"correctOptionId":"a","explanation":"The mean is sensitive to extreme values (outliers).","difficulty":"Medium"},
  {"id":"SAT-10-11-19","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"A trend line on a scatter plot shows:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"general direction of data"},{"id":"b","text":"exact values"},{"id":"c","text":"all data points"},{"id":"d","text":"outliers only"}],"correctOptionId":"a","explanation":"Trend lines show the overall pattern or direction of the data.","difficulty":"Medium"},
  {"id":"SAT-10-11-20","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"Cumulative frequency shows:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"running total"},{"id":"b","text":"individual frequencies"},{"id":"c","text":"percentages"},{"id":"d","text":"averages"}],"correctOptionId":"a","explanation":"Cumulative frequency adds up frequencies as you move through categories.","difficulty":"Medium"},
  {"id":"SAT-10-11-21","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"A misleading graph might:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"truncate the y-axis"},{"id":"b","text":"use clear labels"},{"id":"c","text":"include a title"},{"id":"d","text":"show all data"}],"correctOptionId":"a","explanation":"Truncating the y-axis can exaggerate differences between values.","difficulty":"Hard"},
  {"id":"SAT-10-11-22","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"To calculate the mean from a frequency table:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"sum of (value x frequency) / total frequency"},{"id":"b","text":"sum of frequencies"},{"id":"c","text":"sum of values"},{"id":"d","text":"largest value"}],"correctOptionId":"a","explanation":"Mean = sum(value x frequency) / sum(frequency).","difficulty":"Hard"},
  {"id":"SAT-10-11-23","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"A correlation of -0.9 indicates:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"strong negative relationship"},{"id":"b","text":"strong positive relationship"},{"id":"c","text":"no relationship"},{"id":"d","text":"weak relationship"}],"correctOptionId":"a","explanation":"-0.9 shows a strong negative linear relationship.","difficulty":"Hard"},
  {"id":"SAT-10-11-24","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"The interquartile range measures:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"spread of middle 50%"},{"id":"b","text":"total spread"},{"id":"c","text":"average"},{"id":"d","text":"most common value"}],"correctOptionId":"a","explanation":"IQR = Q3 - Q1, measuring the spread of the middle 50% of data.","difficulty":"Hard"},
  {"id":"SAT-10-11-25","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 11: Informational Graphics","yearEC":"2024 E.C.","questionText":"A stacked bar graph shows:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"parts of each total"},{"id":"b","text":"individual values only"},{"id":"c","text":"trends only"},{"id":"d","text":"correlations"}],"correctOptionId":"a","explanation":"Stacked bar graphs show how parts contribute to each total.","difficulty":"Hard"},
